import{_ as t,o as e,c as i,a8 as r}from"./chunks/framework.OOVqYmW6.js";const h=JSON.parse('{"title":"A practical way to start a Feluqa app","description":"A concise starting point for shaping a Feluqa application around a real workflow and a chosen runtime.","frontmatter":{"sidebarTitle":"Starting an app","title":"A practical way to start a Feluqa app","icon":"square-terminal","description":"A concise starting point for shaping a Feluqa application around a real workflow and a chosen runtime.","summary":"Suggests a brief, use-case-led way to begin a Feluqa application while distinguishing current tools from unfinished target capabilities.","date":"2026-10-30T00:00:00.000Z","lastmod":"2026-10-30T00:00:00.000Z","status":"Implemented","category":"building","tags":["feluqa","application","article"],"collection":"articles","wordCount":143,"readingTime":1},"headers":[],"relativePath":"articles/starting-a-feluqa-app.md","filePath":"articles/starting-a-feluqa-app.md"}'),o={name:"articles/starting-a-feluqa-app.md"};function n(s,a,l,p,c,u){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="a-practical-way-to-start-a-feluqa-app" tabindex="-1">A practical way to start a Feluqa app <a class="header-anchor" href="#a-practical-way-to-start-a-feluqa-app" aria-label="Permalink to &quot;A practical way to start a Feluqa app&quot;">​</a></h1><p>There is no single application shape that fits every Feluqa project. Start with the workflow the application should support and the devices that need to use it. That gives the project a concrete target without assuming a runtime in advance.</p><p>For a current web application, <code>feluqa new &lt;name&gt; --profile web</code> creates the available scaffold. Its composition root selects statically compiled Rust modules through <code>feluqa.toml</code>. Keep business operations in services, and enforce authorization on each server action.</p><p>As the application grows, keep its routes, data, and behavior with the module that owns them. Shared tooling and contracts can support other targets, while each target keeps its own runtime profile. Dynamic module installation and complete standalone runtime shells are still unfinished.</p><p>See <a href="/learn/create-your-first-application">Create your first application</a> for the longer learning path and <a href="/feluqa-internals/">Feluqa’s internals</a> for architecture details.</p>',5)])])}const f=t(o,[["render",n]]);export{h as __pageData,f as default};
